SELECT jsonb_build_array(v.id::text,v.task_id::text,v.version_number::text,v.config_digest,v.config_json,to_char(v.gmt_create,'YYYY-MM-DD"T"HH24:MI:SS.US'),to_char(v.gmt_modified,'YYYY-MM-DD"T"HH24:MI:SS.US'))::text AS canonical_value FROM public.fs_sync_task_version v JOIN public.fs_sync_task t ON t.id=v.task_id WHERE t.task_code='PILOT_PREVIEW' ORDER BY v.version_number,v.id LIMIT 1001
